3	/**
4	 * Converts a telephone number to E.164 form. A leading {@code '+'} and country code are kept when
5	 * present; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
6	 * from the national digits. Spaces, dashes and brackets are stripped. The result must have 8 to 15
7	 * digits after the {@code '+'}, otherwise it cannot form valid E.164.
8	 *
9	 * <p>The national-number length is also checked against the country code: {@code '+61'} requires
10	 * exactly 9 national digits and {@code '+1'} requires exactly 10. A wrong length for the country
11	 * cannot form a valid number and is rejected (a 400 at the endpoint).
12	 */
13	final class TelephoneE164 {
14	
15	    private TelephoneE164() {
16	    }
17	
18	    /**
19	     * Normalizes {@code raw} to E.164, throwing {@link InvalidTelephoneException} when it cannot.
20	     */
21	    static String normalize(String raw) throws InvalidTelephoneException {
22	        String e164 = normalizeOrNull(raw);
23	        if (e164 == null) {
24	            throw new InvalidTelephoneException(raw);
25	        }
26	        return e164;
27	    }
28	
29	    /**
30	     * Normalizes {@code raw} to E.164, returning {@code null} when it cannot form valid E.164.
31	     */
32	    static String normalizeOrNull(String raw) {
33	        if (raw == null) {
34	            return null;
35	        }
36	        // Strip spaces, dashes and brackets, keeping a leading '+' and the digits.
37	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
38	        String national;
39	        if (cleaned.startsWith("+")) {
40	            national = cleaned.substring(1);
41	            if (!national.matches("\\d+")) {
42	                return null;
43	            }
44	        }
45	        else {
46	            if (!cleaned.matches("\\d+")) {
47	                return null;
48	            }
49	            // No country code: assume +61 and drop a single leading '0' from the national digits.
50	            if (cleaned.startsWith("0")) {
51	                cleaned = cleaned.substring(1);
52	            }
53	            national = "61" + cleaned;
54	        }
55	        if (national.length() < 8 || national.length() > 15) {
56	            return null;
57	        }
58	        // National-number length per country code: '+61' => 9 national digits, '+1' => 10.
59	        if (national.startsWith("61")) {
60	            if (national.length() - 2 != 9) {
61	                return null;
62	            }
63	        }
64	        else if (national.startsWith("1")) {
65	            if (national.length() - 1 != 10) {
66	                return null;
67	            }
68	        }
69	        return "+" + national;
70	    }
71	}
