3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical form of an owner's postal {@code address}, applied whenever an owner is created. Trims
8	 * leading/trailing whitespace, collapses runs of whitespace to a single space, upper-cases, and expands
9	 * common street-type abbreviations as whole words ({@code ST -> STREET}, {@code RD -> ROAD},
10	 * {@code AVE -> AVENUE}). So {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
11	 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}. A {@code null} or whitespace-only address
12	 * normalizes to the empty string.
13	 *
14	 * <p>This is the single normalized form used everywhere an address matters: it is what
15	 * {@link NormalizeAddress} stores on the request (so it is persisted and returned), what
16	 * {@link RequireOwnerFields} tests for blankness, and what {@link RejectDuplicateHousehold} and
17	 * {@link HouseholdId} compare, so both duplicate detection and the shared household id agree.
18	 */
19	public final class AddressNormalizer {
20	
21	    private static final Map<String, String> ABBREVIATIONS = Map.of(
22	            "ST", "STREET",
23	            "RD", "ROAD",
24	            "AVE", "AVENUE");
25	
26	    private AddressNormalizer() {
27	    }
28	
29	    public static String normalize(String value) {
30	        if (value == null) {
31	            return "";
32	        }
33	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
34	        if (collapsed.isEmpty()) {
35	            return "";
36	        }
37	        String[] tokens = collapsed.split(" ");
38	        StringBuilder result = new StringBuilder(collapsed.length());
39	        for (int i = 0; i < tokens.length; i++) {
40	            if (i > 0) {
41	                result.append(' ');
42	            }
43	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
44	        }
45	        return result.toString();
46	    }
47	}
